#include<bits/stdc++.h>

using namespace std;

typedef long long ll;

const ll N=2e5+1;

int n,tr[N][26],fail[N],in[N],cnt[N*10],id[N],tot;
string t[N],s;

void insert(string &s,int idx){
    int u=0;
    for(char ch:s){
        int c=ch-'a';
        if(!tr[u][c])
            tr[u][c]=++tot;
        u=tr[u][c];
    }
    id[idx]=u;
}

void build(){
    queue<int>q;
    for(int i=0;i<26;i++)
        if(tr[0][i])
            q.push(tr[0][i]);
    while(!q.empty()){
        int u=q.front();q.pop();
        for(int i=0;i<26;i++)
            if(tr[u][i])
                fail[tr[u][i]]=tr[fail[u]][i],in[tr[fail[u]][i]]++,q.push(tr[u][i]);
            else
                tr[u][i]=tr[fail[u]][i];
    }
}

void query(){
    int u=0;
    for(char ch:s)
        u=tr[u][ch-'a'],cnt[u]++;
}

void topo(){
    queue<int> q;
    for(int i=1;i<=tot;i++)
        if(!in[i])
            q.push(i);
    while(!q.empty()){
        int u=q.front(),v=fail[u];
        q.pop(),cnt[v]+=cnt[u],in[v]--;
        if(!in[v])
            q.push(v);
    }
}

int main(){
    cin>>n;
    for(int i=1;i<=n;i++)
        cin>>t[i],insert(t[i],i);
    build(),cin>>s,query(),topo();
    for(int i=1;i<=n;i++)
        cout<<cnt[id[i]]<<endl;
}//似乎有个变量没用

